(function runMaze(canvasId){
  try{
    const canvas=document.getElementById(canvasId);
    if(!canvas||canvas.nodeName.toLowerCase()!=='canvas'){
      throw new Error('Invalid canvas element');
    }
    const ctx=canvas.getContext('2d');
    const SIZE=500;
    canvas.width=SIZE;
    canvas.height=SIZE;
    const CELL_SIZE=20;
    const COLS=SIZE/CELL_SIZE; //25
    const ROWS=SIZE/CELL_SIZE; //25
    const START={row:1,col:1};
    const GOAL={row:ROWS-2,col:COLS-2};
    const COLORS={
      wall:'#000',
      path:'#fff',
      start:'#0f0',
      goal:'#f00',
      current:'#00f',
      open:'#ff0',
      closed:'#ccc',
      solution:'#0ff'
    };
    const grid=[];
    for(let r=0;r<ROWS;r++){
      grid[r]=[];
      for(let c=0;c<COLS;c++){
        let type='path';
        if(r===0||c===0||r===ROWS-1||c===COLS-1) type='wall';
        grid[r][c]={row:r,col:c,type};
      }
    }
    grid[START.row][START.col].type='start';
    grid[GOAL.row][GOAL.col].type='goal';
    const genSteps=[];
    function divide(x,y,w,h,orientation){
      if(w<2||h<2) return;
      let wallX,wallY,openingX,openingY;
      if(orientation==='h'){
        wallY=y+Math.floor(Math.random()*(h-1))+1;
        openingX=x+Math.floor(Math.random()*w);
        for(let cx=x;cx<x+w;cx++){
          if(cx===openingX)continue;
          genSteps.push({row:wallY,col:cx,type:'wall'});
        }
        genSteps.push({row:wallY,col:openingX,type:'path'});
        divide(x,y,w,wallY-y,'v');
        divide(x,wallY+1,w,h-(wallY-y+1),'v');
      }else{
        wallX=x+Math.floor(Math.random()*(w-1))+1;
        openingY=y+Math.floor(Math.random()*h);
        for(let cy=y;cy<y+h;cy++){
          if(cy===openingY)continue;
          genSteps.push({row:cy,col:wallX,type:'wall'});
        }
        genSteps.push({row:openingY,col:wallX,type:'path'});
        divide(x,y,wallX-x,h,'h');
        divide(wallX+1,y,w-(wallX-x+1),h,'h');
      }
    }
    divide(1,1,COLS-2,ROWS-2,Math.random()<0.5?'h':'v');
    function drawGrid(){
      for(let r=0;r<ROWS;r++){
        for(let c=0;c<COLS;c++){
          const cell=grid[r][c];
          let color=COLORS[cell.type]||COLORS.path;
          ctx.fillStyle=color;
          ctx.fillRect(c*CELL_SIZE,r*CELL_SIZE,CELL_SIZE,CELL_SIZE);
        }
      }
    }
    drawGrid();
    async function animateGen(){
      for(const step of genSteps){
        grid[step.row][step.col].type=step.type;
        drawGrid();
        await new Promise(r=>setTimeout(r,20));
      }
    }
    async function animateSolve(){
      const open=[];
      const closed=new Set();
      const cameFrom=new Map();
      function h(n){return Math.abs(n.row-GOAL.row)+Math.abs(n.col-GOAL.col);}
      grid[START.row][START.col].type='path';
      open.push({...grid[START.row][START.col],g:0,h});
      while(open.length){
        open.sort((a,b)=>a.g+a.h-b.g-b.h);
        const current=open.shift();
        const key=current.row*COLS+current.col;
        if(key===GOAL.row*COLS+GOAL.col){
          const path=[];
          let node=current;
          while(node){
            path.push(node);
            node=cameFrom.get(node.row*COLS+node.col);
          }
          for(const p of path){
            if(grid[p.row][p.col].type!=='start'&&grid[p.row][p.col].type!=='goal'){
              grid[p.row][p.col].type='solution';
              drawGrid();
              await new Promise(r=>setTimeout(r,20));
            }
          }
          return;
        }
        closed.add(key);
        grid[current.row][current.col].type='current';
        drawGrid();
        await new Promise(r=>setTimeout(r,20));
        grid[current.row][current.col].type='closed';
        const dirs=[[1,0],[-1,0],[0,1],[0,-1]];
        for(const [dr,dc] of dirs){
          const nr=current.row+dr,nc=current.col+dc;
          if(nr<0||nr>=ROWS||nc<0||nc>=COLS)continue;
          const neighbor=grid[nr][nc];
          if(neighbor.type==='wall')continue;
          const nkey=nr*COLS+nc;
          if(closed.has(nkey))continue;
          const tentativeG=current.g+1;
          const existing=open.find(n=>n.row===nr&&n.col===nc);
          if(!existing||tentativeG<existing.g){
            cameFrom.set(nkey,{...current});
            if(existing){
              existing.g=tentativeG;
              existing.h=h(existing);
            }else{
              open.push({row:nr,col:nc,g:tentativeG,h});
            }
            if(grid[nr][nc].type==='path'){
              grid[nr][nc].type='open';
            }
          }
        }
        grid[current.row][current.col].type='closed';
        drawGrid();
        await new Promise(r=>setTimeout(r,20));
      }
    }
    animateGen().then(()=>animateSolve());
  }catch(err){console.error(err);}
})();
